cd /tmp/sv-5de44f09da9143c289075d333663bb6a/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | cat > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def pkg_map(projects):
    result = {}
    for p in projects:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = pkg_map(baseline['projects'])
a = pkg_map(after['projects'])

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    proj, fw, pkg = k
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, bv))

print('=== CHANGES ===')
if changes:
    for c in changes: print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('  None')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged[:5]: print(f'  {u[0]} ({u[1]}): {u[2]} @ {u[3]}')
if len(unchanged) > 5: print(f'  ... and {len(unchanged)-5} more')
"

